    @Test
    public void testClose() throws IOException {
        byte[] data = {(byte) 0x01};
        // Use a mock to verify close is called.
        InputStream mockInputStream = new ByteArrayInputStream(data) {
            boolean closed = false;
            @Override
            public void close() throws IOException {
                closed = true;
                super.close();
            }
        };

        try (BitInputStream bis = new BitInputStream(mockInputStream, ByteOrder.BIG_ENDIAN)) {
            bis.readBits(8);
        }
        // Check if the underlying stream's close method was called.
        assertTrue("Underlying stream should be closed", ((BitInputStreamAccessor) mockInputStream).isClosed());
    }

    // Helper class to access the 'closed' status for testing the close method
    private static class BitInputStreamAccessor extends ByteArrayInputStream {
        private boolean closed = false;

        BitInputStreamAccessor(byte[] buf) {
            super(buf);
        }

        @Override
        public void close() throws IOException {
            closed = true;
            super.close();
        }

        public boolean isClosed() {
            return closed;
        }
    }


    @Test
    public void testClearBitCache() throws Exception {
        byte[] data = {(byte) 0b11000000, (byte) 0b00110000}; // 192, 48
        try (BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN)) {
            bis.readBits(4); // Reads 1100. bitsCached = 0b1100, bitsCachedSize = 4.
            // After reading 4 bits, bitsCached = 0xC, bitsCachedSize = 4.
            bis.clearBitCache();
            // The private fields bitsCached and bitsCachedSize are not accessible.
            // We can test clearBitCache indirectly by reading again.
            // After clear, the cache is empty. The next readBits should read fresh from the stream.
            assertEquals(0b11000000L, bis.readBits(8)); // Reads the first byte
        }
    }

    @Test
    public void testReadBitsLittleEndianEdgeCase1() throws Exception {
        // Test case where bitsCachedSize is just enough to not require a new byte read,
        // but the requested bits span across the boundary of bitsCachedSize.
        byte[] data = {(byte) 0b00000011, (byte) 0b11000000}; // 3, 192
        try (BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN)) {
            // Read 5 bits. bitsCached = 0b00000011, bitsCachedSize = 8.
            bis.readBits(5); // Reads 00000
            // Now read 4 bits. bitsCachedSize = 8, count = 4.
            // bitsOut = (bitsCached & MASKS[4]) = 0b00000011 & 0b1111 = 0b0011 = 3L.
            // bitsCached >>>= 4 -> 0b00000011 >>> 4 = 0b00000000.
            // bitsCachedSize -= 4 -> 4.
            assertEquals(0b0011L, bis.readBits(4)); // Extracts the last 4 bits of the first byte.
            // bitsCachedSize = 4. Need 8 bits. Read next byte 0b11000000.
            // bitsCached |= (nextByte << bitsCachedSize) -> 0 | (0b11000000 << 4) = 0b110000000000
            // bitsCachedSize += 8 -> 12.
            // Now extract 8 bits. bitsOut = (bitsCached & MASKS[8]) = 0b110000000000 & 0xFF = 0b11000000 = 192L.
            assertEquals(0b11000000L, bis.readBits(8)); // Reads the second byte
        }
    }

    @Test
    public void testReadBitsBigEndianEdgeCase1() throws Exception {
        // Test case where bitsCachedSize is just enough to not require a new byte read,
        // but the requested bits span across the boundary of bitsCachedSize.
        byte[] data = {(byte) 0b00000011, (byte) 0b11000000}; // 3, 192
        try (BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN)) {
            // Read 5 bits. bitsCached = 0b00000011, bitsCachedSize = 8.
            bis.readBits(5); // Reads 00000
            // Now read 4 bits. bitsCachedSize = 8, count = 4.
            // bitsOut = (bitsCached >> (bitsCachedSize - count)) & MASKS[count]
            // bitsOut = (0b00000011 >> (8 - 4)) & MASKS[4] = (0b00000011 >> 4) & 0b1111 = 0b0000 & 0b1111 = 0L.
            // bitsCachedSize -= 4 -> 4.
            assertEquals(0L, bis.readBits(4)); // Extracts the first 4 bits of the first byte.
            // State: bitsCached=0b00000011, bitsCachedSize=4. The remaining bits in cache are 0b0011.
            // Need 8 bits. bitsCachedSize = 4.
            // While loop: 4 < 8 && 4 < 57 -> true.
            // Read next byte 0b11000000.
            // bitsCached <<= 8 -> 0b0011 << 8 = 0b0011000000.
            // bitsCached |= nextByte -> 0b0011000000 | 0b11000000 = 0b001111000000.
            // bitsCachedSize += 8 -> 12.
            // Loop ends: 12 < 8 is false.
            // if (bitsCachedSize < count) -> 12 < 8 is false.
            // overflowBits = 0.
            // bitsOut = (bitsCached >> (bitsCachedSize - count)) & MASKS[count]
            // bitsOut = (0b001111000000 >> (12 - 8)) & MASKS[8]
            // bitsOut = (0b001111000000 >> 4) & 0xFF
            // bitsOut = 0b00111100 & 0xFF = 0x3C = 60L.
            assertEquals(60L, bis.readBits(8)); // Reads the remaining 4 bits from the first byte (0011) and the first 4 bits from the second byte (1100).
        }
    }

    @Test
    public void testReadBitsLittleEndianMultipleReads() throws Exception {
        byte[] data = {(byte) 0b11110000, (byte) 0b00001111, (byte) 0b10101010};
        try (BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.LITTLE_ENDIAN)) {
            // Read 4 bits. Reads the last 4 bits of the first byte (0000).
            // bitsCached = 0b11110000, bitsCachedSize=8.
            // bitsOut = bitsCached & MASKS[4] = 0b0000.
            // bitsCached >>>= 4 -> 0b00001111. bitsCachedSize -= 4 -> 4.
            assertEquals(0b0000L, bis.readBits(4)); 

            // Read 4 bits. bitsCachedSize=4, count=4.
            // bitsOut = bitsCached & MASKS[4] = 0b00001111 & 0b1111 = 0b1111.
            // bitsCached >>>= 4 -> 0b00000000. bitsCachedSize -= 4 -> 0.
            assertEquals(0b1111L, bis.readBits(4)); // Reads the first 4 bits of the second byte.

            // Read 8 bits. bitsCachedSize=0, count=8.
            // Reads the third byte 0b10101010.
            // bitsCached |= (nextByte << bitsCachedSize) -> 0 | (0b10101010 << 0) = 0b10101010.
            // bitsCachedSize += 8 -> 8.
            // bitsOut = bitsCached & MASKS[8] = 0b10101010.
            // bitsCached >>>= 8 -> 0. bitsCachedSize -= 8 -> 0.
            assertEquals(0b10101010L, bis.readBits(8)); // Reads the third byte.
        }
    }

